    "P2": timedelta(minutes=30),
    "P3": timedelta(hours=4),
    "P4": timedelta(hours=8),  # 1 个工作日 = 8 小时服务时段
}

SERVICE_START = time(9, 0)
SERVICE_END = time(18, 0)

# 累计推进时的保护性上限：8 小时目标最多跨越约 3 个自然日。
_MAX_DAYS = 10000


def parse_instant(text: str) -> datetime:
