def _next_window_start(t: datetime) -> datetime:
    """t 之后下一个服务窗口的起点（t 正处于窗口起点时返回其本身）。"""
    if t.weekday() < 5 and t.timetz() < SERVICE_START:
        return datetime.combine(t.date(), SERVICE_START, tzinfo=t.tzinfo)
