def sla_state(
    submitted: datetime,
    priority: str,
    pauses: list[tuple[datetime, datetime | None]],
    now: datetime,
) -> tuple[datetime, timedelta, datetime | None]:
    """计算查看工单时的 ``(截止时刻, 已耗服务时长, 冻结时刻)``。

    ``pauses`` 按时间顺序排列，止点为 None 表示暂停中。恢复后截止按
    “从恢复时刻继续累计剩余目标服务时长”顺延；暂停中截止与已耗时都
    按暂停起点冻结（``freeze`` 返回该起点，否则为 None）。
    """
    target = RESPONSE_TARGETS[priority]

    open_start: datetime | None = None
    closed: list[tuple[datetime, datetime]] = []
    for p_start, p_end in pauses:
        if p_end is None:
            open_start = p_start
        else:
            closed.append((p_start, p_end))

    # 逐段推进：运行段消耗剩余目标，暂停段不计时。
    remaining = target
    cursor = submitted
    for p_start, p_end in closed:
        consumed = business_time(cursor, p_start)
        if consumed >= remaining:
            # 截止在本次暂停之前已经到达，之后的状态不再影响截止。
            return advance(cursor, remaining), business_time(
                submitted, min(now, p_start), closed
            ), None
        remaining -= consumed
        cursor = p_end

    if open_start is not None:
        consumed = business_time(cursor, open_start)
        freeze = open_start
        if consumed >= remaining:
            due = advance(cursor, remaining)
        else:
            # 剩余目标按“立即恢复”投影出截止；查看时在暂停时刻冻结。
            due = advance(open_start, remaining - consumed)
        elapsed = target - max(remaining - consumed, timedelta(0))
        return due, elapsed, freeze

    due = advance(cursor, remaining)
    elapsed = business_time(submitted, now, pauses)
    return due, elapsed, None


def floor_minutes(delta: timedelta) -> int:
    """时长向下取整为整分钟。"""
    return int(delta.total_seconds() // 60)

